window.CenizasPreferences=(()=>{let auto=true;try{const stored=localStorage.getItem('cenizas-battle-auto-close');if(stored!==null)auto=stored==='true';}catch{/* optional storage/API unavailable; safe fallback */}function sync(){document.querySelectorAll('[data-battle-auto]').forEach(el=>el.checked=auto);}document.querySelectorAll('[data-battle-auto]').forEach(el=>el.addEventListener('change',()=>{auto=el.checked;try{localStorage.setItem('cenizas-battle-auto-close',String(auto));}catch{/* optional storage/API unavailable; safe fallback */}sync();window.dispatchEvent(new Event('battle-auto-change'));}));sync();return {get auto(){return auto;}};})();
